import{_ as e,o as s,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"71. Debugging with gdb","description":"The Little Book of C — 71. Debugging with gdb","frontmatter":{"title":"71. Debugging with gdb","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 71. Debugging with gdb","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":71,"sidebarWeight":71,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/08-Debugging Testing Profiling/071-Debugging with gdb.md"};function p(o,a,l,c,d,g){return s(),n("div",null,[...a[0]||(a[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/071-Debugging with gdb)</p><p>Every C programmer eventually meets a segmentation fault, and that’s when you discover your most powerful companion: gdb, the GNU Debugger. Debugging isn’t about luck; it’s about learning to inspect a program as it runs, to pause time, and to see what the computer is really doing.</p><p>Let’s learn how to use gdb to find bugs, inspect memory, trace crashes, and truly understand your code.</p><h4 id="step-1-compiling-with-debug-information" tabindex="-1">Step 1. Compiling with Debug Information <a class="header-anchor" href="#step-1-compiling-with-debug-information" aria-label="Permalink to &quot;Step 1. Compiling with Debug Information&quot;">​</a></h4><p>Before you can debug, you need to tell the compiler to include symbol information (variable names, line numbers, etc.). Use the<code>-g</code> flag:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g main.c -o main</span></span></code></pre></div><p>You can now open it in gdb:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb ./main</span></span></code></pre></div><h4 id="step-2-starting-and-running-your-program" tabindex="-1">Step 2. Starting and Running Your Program <a class="header-anchor" href="#step-2-starting-and-running-your-program" aria-label="Permalink to &quot;Step 2. Starting and Running Your Program&quot;">​</a></h4><p>Inside gdb, you can run your program just like normal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) run</span></span></code></pre></div><p>If it crashes, you’ll get something like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program received signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>0x000000000040114a in buggy_function () at main.c:12</span></span>
<span class="line"><span>12        *ptr = 42;</span></span></code></pre></div><p>You now know exactly where it failed.</p><h4 id="step-3-setting-breakpoints" tabindex="-1">Step 3. Setting Breakpoints <a class="header-anchor" href="#step-3-setting-breakpoints" aria-label="Permalink to &quot;Step 3. Setting Breakpoints&quot;">​</a></h4><p>A breakpoint tells gdb to pause before executing a specific line or function.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) break main</span></span>
<span class="line"><span>Breakpoint 1 at 0x40113b: file main.c, line 5.</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>When the program stops, you can inspect state:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) print variable_name</span></span>
<span class="line"><span>(gdb) next</span></span>
<span class="line"><span>(gdb) step</span></span></code></pre></div><ul><li><code>next</code> executes the next line (skipping function calls).</li><li><code>step</code> goes into a function call.</li></ul><h4 id="step-4-example-a-simple-bug" tabindex="-1">Step 4. Example: A Simple Bug <a class="header-anchor" href="#step-4-example-a-simple-bug" aria-label="Permalink to &quot;Step 4. Example: A Simple Bug&quot;">​</a></h4><p>Here’s a program with a classic segmentation fault.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void buggy(void) {</span></span>
<span class="line"><span>    int *p = NULL;</span></span>
<span class="line"><span>    *p = 10;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Before crash\\n&quot;);</span></span>
<span class="line"><span>    buggy();</span></span>
<span class="line"><span>    printf(&quot;After crash\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and debug:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g bug.c -o bug</span></span>
<span class="line"><span>gdb ./bug</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Program received signal SIGSEGV, Segmentation fault.</span></span>
<span class="line"><span>0x0000555555555159 in buggy () at bug.c:5</span></span>
<span class="line"><span>5        *p = 10;</span></span></code></pre></div><p>Now inspect:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) backtrace</span></span>
<span class="line"><span>#0 buggy () at bug.c:5</span></span>
<span class="line"><span>#1 main () at bug.c:10</span></span></code></pre></div><p>You’ve just traced the crash from main to the exact faulty line.</p><h4 id="step-5-inspecting-variables" tabindex="-1">Step 5. Inspecting Variables <a class="header-anchor" href="#step-5-inspecting-variables" aria-label="Permalink to &quot;Step 5. Inspecting Variables&quot;">​</a></h4><p>You can view variable values anytime:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) print x</span></span>
<span class="line"><span>(gdb) print *ptr</span></span></code></pre></div><p>You can also modify them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) set variable x = 100</span></span></code></pre></div><p>To list all local variables:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info locals</span></span></code></pre></div><h4 id="step-6-navigating-execution" tabindex="-1">Step 6. Navigating Execution <a class="header-anchor" href="#step-6-navigating-execution" aria-label="Permalink to &quot;Step 6. Navigating Execution&quot;">​</a></h4><p>Common gdb commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>Action</th></tr></thead><tbody><tr><td><code>run</code></td><td>Start the program</td></tr><tr><td><code>break N</code></td><td>Stop at line N</td></tr><tr><td><code>next</code></td><td>Run next line</td></tr><tr><td><code>step</code></td><td>Step into function</td></tr><tr><td><code>continue</code></td><td>Resume until next breakpoint</td></tr><tr><td><code>finish</code></td><td>Run until function returns</td></tr><tr><td><code>backtrace</code></td><td>Show call stack</td></tr><tr><td><code>info locals</code></td><td>List local vars</td></tr><tr><td><code>print VAR</code></td><td>Show value</td></tr><tr><td><code>quit</code></td><td>Exit gdb</td></tr></tbody></table><h4 id="step-7-watching-variables" tabindex="-1">Step 7. Watching Variables <a class="header-anchor" href="#step-7-watching-variables" aria-label="Permalink to &quot;Step 7. Watching Variables&quot;">​</a></h4><p>You can set watchpoints, gdb stops when a variable changes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int counter = 0;</span></span>
<span class="line"><span>for (int i = 0; i &lt; 10; i++)</span></span>
<span class="line"><span>    counter += i;</span></span></code></pre></div><p>In gdb:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) watch counter</span></span>
<span class="line"><span>(gdb) run</span></span></code></pre></div><p>Every time<code>counter</code> changes, the program pauses, showing where it happened.</p><h4 id="step-8-conditional-breakpoints" tabindex="-1">Step 8. Conditional Breakpoints <a class="header-anchor" href="#step-8-conditional-breakpoints" aria-label="Permalink to &quot;Step 8. Conditional Breakpoints&quot;">​</a></h4><p>Sometimes you only want to stop under specific conditions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) break loop.c:25 if i &gt; 100</span></span></code></pre></div><p>This breakpoint triggers only when<code>i</code> exceeds 100.</p><h4 id="step-9-inspecting-memory-and-registers" tabindex="-1">Step 9. Inspecting Memory and Registers <a class="header-anchor" href="#step-9-inspecting-memory-and-registers" aria-label="Permalink to &quot;Step 9. Inspecting Memory and Registers&quot;">​</a></h4><p>You can inspect raw memory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) x/10x &amp;array</span></span></code></pre></div><p>This prints 10 hexadecimal words starting at<code>&amp;array</code>.</p><p>Or view registers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info registers</span></span></code></pre></div><p>This is useful for low-level debugging (e.g., compilers, OS kernels, embedded code).</p><h4 id="step-10-tiny-code-debugging-a-logic-bug" tabindex="-1">Step 10. Tiny Code: Debugging a Logic Bug <a class="header-anchor" href="#step-10-tiny-code-debugging-a-logic-bug" aria-label="Permalink to &quot;Step 10. Tiny Code: Debugging a Logic Bug&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int sum = 0;</span></span>
<span class="line"><span>    for (int i = 1; i &lt;= 5; i++) {</span></span>
<span class="line"><span>        sum = sum + i;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Sum = %d\\n&quot;, sum); // should be 15</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Introduce a bug:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for (int i = 1; i &lt;= 5; i++); // extra semicolon!</span></span></code></pre></div><p>Compile and debug:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g bug.c -o bug</span></span>
<span class="line"><span>gdb ./bug</span></span>
<span class="line"><span>(gdb) break main</span></span>
<span class="line"><span>(gdb) run</span></span>
<span class="line"><span>(gdb) print sum</span></span>
<span class="line"><span>(gdb) next</span></span>
<span class="line"><span>(gdb) print sum</span></span></code></pre></div><p>You’ll see that<code>sum</code> never changes, because the loop body was empty.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Debugging is how you learn to think like the machine:</p><ul><li>You can inspect what happens between lines.</li><li>You can see every variable’s value.</li><li>You can find segmentation faults in seconds.</li></ul><p>Learning gdb teaches you how C really runs, from stack frames to pointers.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a program that crashes (e.g., use a null pointer) and trace the cause with gdb.</li><li>Use<code>next</code> and<code>step</code> to trace a recursive function.</li><li>Set a watchpoint on a variable in a loop.</li><li>Add a conditional breakpoint that triggers only when a value exceeds a limit.</li><li>Explore<code>backtrace</code> and<code>info locals</code> after a crash.</li></ol><p>Next, you’ll learn how to detect hidden memory errors, leaks, invalid frees, and buffer overflows, using the indispensable Valgrind tool.</p>`,71)])])}const h=e(i,[["render",p]]);export{u as __pageData,h as default};
